        neighbors_v = [w for w in range(n) if (v, w) in G or (w, v) in G]
        common_neighbors = set(neighbors_u).intersection(neighbors_v)
        volume += len(common_neighbors) / (len(neighbors_u) * len(neighbors_v))
    return volume

